from pocket_coffea.lib.cut_functions import (
    get_HLT_trigger_cut,
    get_nObjects,
    get_btagging
)

# Parameters including semileptonic trigger selection
parameters = {
    "year": 2018,
    "dataset_primary": "semileptonic",
    "semileptonic_triggers": ["HLT_IsoMu24", "HLT_IsoTkMu24"],
}

# Skim cuts (loose cuts for data reduction)
skim_cuts = {
    "HLT_semileptonic": get_HLT_trigger_cut(
        dataset=parameters["dataset_primary"],
        triggers=parameters["semileptonic_triggers"]
    ),
}

# Preselection cuts (tighter cuts for analysis)
preselection_cuts = {
    "HLT_semileptonic": get_HLT_trigger_cut(
        dataset=parameters["dataset_primary"],
        triggers=parameters["semileptonic_triggers"]
    ),
    "N_jets": get_nObjects(
        collection="JetGood",
        pt_min=30,
        n_min=4
    ),
    "N_btags": get_btagging(
        n_min=2
    ),
}

print("Skim cuts:", skim_cuts)
print("Preselection cuts:", preselection_cuts)

